import { loadFont as loadHead } from "@remotion/google-fonts/Anton";
import { loadFont as loadTxt } from "@remotion/google-fonts/Inter";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, interpolate, OffthreadVideo, Sequence, staticFile, useCurrentFrame } from "remotion";

// ECMP / Projeto CFC — v3, 16/11/2026. O o diretor achou a v2 "feio, preciso de mais motion".
// Mesma voz e mesmos tempos da v2; agora alterna filmagem e cena desenhada a cada frase (metade do vídeo em motion):
// bola que abre o vídeo, brasão, degraus por idade, idades grandes, quadro de fundamentos, barras que se desenham,
// quadra que vira campo, mapa de locais com câmera, ECMP que vira CFC. Área segura da v2 mantida (x 120–960, y 250–1480).

const { fontFamily: HEAD } = loadHead("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: TXT } = loadTxt("normal", { weights: ["600", "700", "800"], subsets: ["latin", "latin-ext"] });

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const C11_FPS = 30;
const OFF = 0.3;
export const C11_DUR = 82.75;
// v11: narração do Mário com a frase do Pedro Lima no lugar do São Paulo. As cenas continuam escritas no tempo da voz antiga (C11_DUR = 82,75 s);
// W leva o tempo da voz nova ao tempo antigo, por âncoras palavra a palavra (edit/ancoras-v11.json nas notas do cliente).
const ANC: [number, number][] = [[0, 0], [0.16, 0.18], [0.44, 0.48], [0.61, 0.66], [1.59, 1.3], [2.28, 2.33], [2.77, 2.59], [3.19, 3.17], [3.63, 3.62], [4.0, 3.94], [4.55, 4.52], [5.6, 5.96], [6.07, 6.13], [6.79, 6.84], [7.58, 7.48], [8.28, 8.31], [9.49, 9.26], [10.31, 10.72], [10.78, 11.6], [11.75, 12.15], [12.15, 12.92], [13.04, 13.6], [13.59, 14.46], [14.04, 15.41], [14.95, 16.15], [15.4, 17.0], [16.42, 19.14], [18.16, 20.0], [18.92, 21.6], [19.42, 22.3], [20.42, 24.02], [21.42, 24.31], [22.28, 25.7], [23.49, 26.81], [25.02, 29.18], [26.0, 29.85], [26.5, 30.53], [27.09, 31.0], [27.81, 31.83], [28.34, 32.45], [29.78, 34.22], [30.54, 34.6], [31.12, 35.02], [32.02, 36.14], [32.66, 36.62], [33.33, 37.22], [34.81, 39.4], [35.41, 39.84], [36.55, 40.59], [37.28, 41.43], [37.88, 42.02], [39.05, 43.72], [39.67, 44.3], [40.7, 45.4], [41.53, 45.55], [42.34, 46.8], [43.45, 49.28], [45.49, 50.05], [46.29, 50.36], [46.77, 51.0], [47.53, 52.64], [48.29, 54.1], [48.82, 54.45], [49.07, 55.45], [49.58, 55.8], [50.02, 56.63], [50.96, 57.73], [51.48, 59.29], [51.68, 60.39], [53.25, 63.26], [53.49, 63.78], [54.47, 64.6], [55.55, 65.7], [56.8, 67.04], [56.949999999999996, 68.44], [57.949999999999996, 70.75], [58.58, 71.2], [59.629999999999995, 72.17], [60.37, 73.23], [60.72, 73.82], [62.32, 75.51], [63.39999999999999, 76.03], [63.83, 76.85], [64.31, 77.4], [64.59, 78.36], [65.45, 79.22], [66.64, 80.24], [69.13, 82.75]];
const AN = ANC.map((x) => x[0]), AO = ANC.map((x) => x[1]);
const W = (x: number) => interpolate(x, AN, AO, { extrapolateLeft: "extend", extrapolateRight: "extend" });
const Winv = (x: number) => interpolate(x, AO, AN, { extrapolateLeft: "extend", extrapolateRight: "extend" });
export const C11_NEW_DUR = 69.13;
export const C11_FRAMES = Math.round(C11_NEW_DUR * C11_FPS);
const NAVY = "#131A2E";
const NAVY2 = "#1D2846";
const NAVY3 = "#27365C";
const RED = "#B8232F";
const GOLD = "#F2B820";

const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const SPR = Easing.out(Easing.back(1.2));
const IO = Easing.inOut(Easing.cubic);
const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const sp = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: SPR });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: IO });

// ───────── cenas ─────────
type Entry = "punch" | "slide" | "whip" | "pull" | "flood";
type Shot = { a: number; src: string; from?: number; e: Entry; pos?: string; fit?: boolean; fitW?: number; zm?: number };
const SHOTS: Shot[] = [
  { a: 0.0, src: "d:hook", e: "punch" },
  { a: 1.9, src: "v6", from: 3.0, e: "pull" },
  { a: 3.1, src: "d:crest", e: "flood" },
  { a: 5.4, src: "f1", e: "punch", fit: true },
  { a: 7.9, src: "d:steps", e: "whip" },
  { a: 10.4, src: "d:age1", e: "punch" },
  { a: 12.8, src: "v7", from: 8.0, e: "flood" },
  { a: 15.3, src: "d:grid", e: "whip" },
  { a: 18.6, src: "d:age2", e: "slide" },
  { a: 20.9, src: "v5", from: 3.5, e: "punch", fit: true },
  { a: 24.0, src: "d:bars", e: "flood" },
  { a: 27.9, src: "d:age3", e: "whip" },
  { a: 30.0, src: "v1", from: 10.0, e: "pull", zm: 1.2 },
  { a: 33.9, src: "d:quadra", e: "flood" },
  { a: 37.2, src: "v4", from: 4.5, e: "slide" },
  { a: 39.5, src: "d:locs", e: "whip" },
  { a: 48.9, src: "pp", e: "flood" },
  { a: 52.3, src: "d:ecmp", e: "slide" },
  { a: 60.3, src: "v1", from: 13.55, e: "punch", zm: 1.2 }, // zm: a faixa "Copa Jampa" do pé da filmagem fica fora do quadro
  { a: 63.6, src: "patleta", e: "punch", fit: true, fitW: 640 },
  { a: 66.75, src: "d:venda", e: "flood" },
  { a: 73.45, src: "d:end", e: "flood" },
];

// 48,9–52,3 · montagem: os quatro professores e, na troca, o do troféu por cima no canto
const Profs: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const z = 1 + 0.04 * lin(t, a, b + 0.4);
  const e2 = sp(t, 50.6, 0.5);
  const out = 1 - lin(t, b - 0.07, b + 0.01);
  const card = (src: string, st: React.CSSProperties, rot: number) => (
    <div style={{ position: "absolute", ...st, padding: 12, background: "#FFFFFF", borderRadius: 6, boxShadow: "0 30px 70px rgba(0,0,0,0.5)", transform: `rotate(${rot}deg)` }}>
      <Img src={staticFile(`contas/ecmp/${src}.jpg`)} style={{ width: "100%", display: "block" }} />
    </div>
  );
  return (
    <AbsoluteFill>
      <Img src={staticFile("contas/ecmp/p1.jpg")} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", transform: "scale(1.25)", filter: "blur(38px) brightness(0.5) saturate(1.1)" }} />
      <AbsoluteFill style={{ transform: `scale(${z.toFixed(4)})`, transformOrigin: "50% 52%", opacity: out }}>
        {card("p1", { left: 50, top: 585, width: 680 }, -3)}
        <div style={{ position: "absolute", inset: 0, opacity: Math.min(1, e2 * 3), transform: `translateY(${((1 - e2) * 260).toFixed(1)}px) scale(${(1.25 - 0.25 * e2).toFixed(4)})`, transformOrigin: "720px 1210px" }}>
          {card("p2", { left: 510, top: 960, width: 420 }, 3)}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

const Media: React.FC<{ s: Shot; t: number; b: number }> = ({ s, t, b }) => {
  if (s.src === "pp") return <Profs t={t} a={s.a} b={b} />;
  const z = 1.02 + (s.src.startsWith("v") ? 0.09 : s.src.startsWith("p") ? 0.04 : 0.16) * lin(t, s.a, b + 0.4); // aproximação
  const isV = s.src.startsWith("v");
  const file = staticFile(`contas/ecmp/${s.src}.${isV ? "mp4" : "jpg"}`);
  const el = (st: React.CSSProperties) =>
    isV ? (
      <Sequence from={Math.round((Winv(s.a) + OFF) * C11_FPS)} layout="none">
        <OffthreadVideo src={file} startFrom={Math.round((s.from ?? 0) * C11_FPS)} muted style={st} />
      </Sequence>
    ) : (
      <Img src={file} style={st} />
    );
  const cover: React.CSSProperties = { position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover", objectPosition: s.pos ?? "50% 50%" };
  if (!s.fit) return el({ ...cover, transform: `scale(${(z * (s.zm ?? 1)).toFixed(4)})`, transformOrigin: s.zm ? "50% 30%" : undefined });
  return (
    <AbsoluteFill>
      {el({ ...cover, transform: "scale(1.25)", filter: "blur(38px) brightness(0.55) saturate(1.1)" })}
      <div style={{ position: "absolute", left: 0, right: 0, top: 250, height: s.fitW ? 860 : 820, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{ width: s.fitW ?? 1080, transform: `scale(${(z - 0.01).toFixed(4)})`, boxShadow: "0 30px 80px rgba(0,0,0,0.45)" }}>{el({ width: "100%", display: "block" })}</div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── texto ─────────
const hs = (size: number, color: string, shadow = true): React.CSSProperties => ({ fontFamily: HEAD, fontWeight: 400, fontSize: size, lineHeight: 1.04, color, textTransform: "uppercase", letterSpacing: "0.01em", textShadow: shadow ? "0 4px 24px rgba(0,0,0,0.45)" : "none" });
const clean = (w: string) => w.replace(/[.,:!?]/g, "").toUpperCase();
const Words: React.FC<{ t: number; at: number; text: string; size: number; hl?: string[]; step?: number; color?: string; width?: number; shadow?: boolean }> = ({ t, at, text, size, hl = [], step = 0.05, color = "#FFFFFF", width = 790, shadow = true }) => (
  <div style={{ width, display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: size * 0.24 }}>
    {text.split(" ").map((w, i) => {
      const e = sp(t, at + i * step, 0.4);
      return (
        <span key={i} style={{ display: "inline-block", overflow: "hidden", paddingTop: size * 0.22, marginTop: -size * 0.22, paddingBottom: size * 0.05 }}>
          <span style={{ ...hs(size, hl.includes(clean(w)) ? GOLD : color, shadow), display: "inline-block", whiteSpace: "nowrap", transform: `translateY(${((1 - e) * 135).toFixed(1)}%)` }}>{w}</span>
        </span>
      );
    })}
  </div>
);
const Kicker: React.FC<{ t: number; at: number; children: string; bg?: string; fg?: string }> = ({ t, at, children, bg = GOLD, fg = NAVY }) => {
  const e = k(t, at, 0.45);
  return (
    <div style={{ overflow: "hidden", padding: "4px 0" }}>
      <div style={{ background: bg, color: fg, borderRadius: 14, padding: "12px 28px", fontFamily: TXT, fontWeight: 800, fontSize: 34, letterSpacing: "0.08em", textTransform: "uppercase", whiteSpace: "nowrap", transform: `translateY(${((1 - e) * 110).toFixed(0)}%)` }}>{children}</div>
    </div>
  );
};
// texto que sobe por máscara e fica parado
const Up: React.FC<{ t: number; at: number; style: React.CSSProperties; children: React.ReactNode; pad?: number }> = ({ t, at, style, children, pad = 30 }) => (
  <div style={{ overflow: "hidden", paddingTop: pad, marginTop: -pad }}>
    <div style={{ ...style, whiteSpace: "nowrap", transform: `translateY(${((1 - sp(t, at, 0.42)) * 140).toFixed(1)}%)` }}>{children}</div>
  </div>
);

// legenda nas filmagens: base em 1440 px
type Cap = { a: number; b: number; kick?: string; kickAt?: number; head?: string; headAt?: number; size?: number; hl?: string[]; sub?: string; subAt?: number; rot?: [number, string][]; top?: number };
const CAPS: Cap[] = [
  { a: 1.95, b: 3.05, head: "Venha desenvolver esse talento", headAt: 1.95, size: 100, hl: ["TALENTO"] },
  { a: 5.5, b: 7.85, head: "Formação completa", headAt: 5.95, size: 120, hl: ["COMPLETA"] },
  { a: 12.85, b: 15.25, kick: "Futsal · 4 e 5 anos", kickAt: 12.85, rot: [[12.85, "Controle"], [13.6, "Domínio"], [14.7, "Passes"]] },
  { a: 20.95, b: 23.95, kick: "A partir de 10 anos", kickAt: 20.95, rot: [[20.95, "Trabalho em equipe"], [22.68, "Socialização"]] },
  { a: 30.05, b: 33.8, kick: "De 11 a 15 anos", kickAt: 30.05, head: "Projeto CFC", headAt: 30.1, size: 130, hl: ["CFC"], sub: "Campeão Formando Campeões", subAt: 31.82 },
  { a: 37.25, b: 39.35, kick: "Treinos no campo da", kickAt: 37.25, head: "UNIPÊ", headAt: 37.95, size: 150, hl: ["UNIPÊ"] },
  { a: 49.0, b: 52.15, top: 270, head: "Os melhores professores", headAt: 49.28, size: 90, hl: ["PROFESSORES"], sub: "para cada categoria", subAt: 50.36 },
  { a: 63.65, b: 66.6, head: "Pedro Lima", headAt: 63.8, size: 140, hl: ["LIMA"], sub: "Atleta revelado pelo\nMeninos da Paraíba", subAt: 64.6 },
  { a: 60.4, b: 63.45, head: "A escola que forma verdadeiros campeões", headAt: 60.42, size: 100, hl: ["CAMPEÕES"] },
];
const Rot: React.FC<{ t: number; items: [number, string][]; b: number }> = ({ t, items, b }) => {
  const j = items.findIndex(([a], i) => t >= a && (i + 1 >= items.length || t < items[i + 1][0]));
  if (j < 0) return <div style={{ height: 240 }} />;
  const [a, w] = items[j];
  const end = j + 1 < items.length ? items[j + 1][0] : b;
  const e = sp(t, a, 0.32);
  const out = 1 - lin(t, end - 0.07, end);
  const size = w.length > 14 ? 100 : 128;
  return (
    <div style={{ height: 240, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "flex-end", gap: 14, opacity: out }}>
      <div style={{ overflow: "hidden", paddingTop: size * 0.22, marginTop: -size * 0.22, paddingBottom: 6 }}>
        <div style={{ ...hs(size, "#FFFFFF"), maxWidth: 800, textAlign: "center", transform: `translateY(${((1 - e) * 135).toFixed(1)}%)` }}>{w}</div>
      </div>
      <div style={{ width: 160 * k(t, a + 0.08, 0.35), height: 8, borderRadius: 4, background: GOLD }} />
    </div>
  );
};
const CapBlock: React.FC<{ c: Cap; t: number }> = ({ c, t }) => {
  if (t < c.a || t > c.b) return null;
  const out = 1 - lin(t, c.b - 0.1, c.b);
  return (
    <div style={{ position: "absolute", left: 120, right: 120, ...(c.top ? { top: c.top } : { bottom: 480 }), display: "flex", flexDirection: "column", alignItems: "center", gap: 26, opacity: out }}>
      {c.kick && <Kicker t={t} at={c.kickAt ?? c.a}>{c.kick}</Kicker>}
      {c.head && <Words t={t} at={c.headAt ?? c.a + 0.08} text={c.head} size={c.size ?? 100} hl={c.hl} />}
      {c.sub && (
        <div style={{ overflow: "hidden" }}>
          <div style={{ fontFamily: TXT, fontWeight: 700, fontSize: 44, lineHeight: 1.2, color: "#FFFFFF", textAlign: "center", maxWidth: 800, whiteSpace: "pre-line", textShadow: "0 3px 18px rgba(0,0,0,0.5)", transform: `translateY(${((1 - k(t, c.subAt ?? c.a, 0.45)) * 110).toFixed(0)}%)` }}>{c.sub}</div>
        </div>
      )}
      {c.rot && <Rot t={t} items={c.rot} b={c.b} />}
    </div>
  );
};

// ───────── peças desenhadas ─────────
const pent = (cx: number, cy: number, r: number, rot = -90) =>
  Array.from({ length: 5 }, (_, i) => {
    const a = ((rot + i * 72) * Math.PI) / 180;
    return `${(cx + r * Math.cos(a)).toFixed(2)},${(cy + r * Math.sin(a)).toFixed(2)}`;
  }).join(" ");
const Ball: React.FC<{ s: number; rot?: number }> = ({ s, rot = 0 }) => (
  <svg width={s} height={s} viewBox="-50 -50 100 100" style={{ display: "block", overflow: "visible" }}>
    <defs><clipPath id="bl"><circle r="47" /></clipPath></defs>
    <circle r="47" fill="#FFFFFF" />
    <g clipPath="url(#bl)" transform={`rotate(${rot.toFixed(1)})`}>
      <polygon points={pent(0, 0, 15)} fill={NAVY} />
      {Array.from({ length: 5 }, (_, i) => {
        const a = ((-90 + i * 72) * Math.PI) / 180;
        const x1 = 15 * Math.cos(a), y1 = 15 * Math.sin(a), x2 = 33 * Math.cos(a), y2 = 33 * Math.sin(a);
        return (
          <g key={i}>
            <line x1={x1} y1={y1} x2={x2} y2={y2} stroke={NAVY} strokeWidth="2.6" />
            <polygon points={pent(44 * Math.cos(a), 44 * Math.sin(a), 13, -90 + i * 72 + 180)} fill={NAVY} />
          </g>
        );
      })}
    </g>
    <circle r="47" fill="none" stroke="rgba(0,0,0,0.18)" strokeWidth="2" />
  </svg>
);
const Check: React.FC<{ s: number; on: number }> = ({ s, on }) => (
  <svg width={s} height={s} viewBox="0 0 40 40">
    <circle cx="20" cy="20" r="18" fill={on > 0 ? GOLD : "none"} stroke={GOLD} strokeWidth="3" opacity={0.4 + 0.6 * Math.min(1, on * 2)} />
    <path d="M11 20.5l6 6 12-13" fill="none" stroke={NAVY} strokeWidth="4.5" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="30" strokeDashoffset={(30 * (1 - on)).toFixed(1)} />
  </svg>
);
const Pin: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><path d="M12 2C8.1 2 5 5.1 5 9c0 5.2 7 13 7 13s7-7.8 7-13c0-3.9-3.1-7-7-7zm0 9.5A2.5 2.5 0 1 1 12 6.5a2.5 2.5 0 0 1 0 5z" fill={GOLD} /></svg>
);
const Phone: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 24 24"><path d="M6.6 10.8a15.1 15.1 0 0 0 6.6 6.6l2.2-2.2c.3-.3.7-.4 1-.2 1.1.4 2.3.6 3.6.6.6 0 1 .4 1 1V20c0 .6-.4 1-1 1A17 17 0 0 1 3 4c0-.6.4-1 1-1h3.5c.6 0 1 .4 1 1 0 1.3.2 2.5.6 3.6.1.3 0 .7-.2 1z" fill={NAVY} /></svg>
);
// brasão com um brilho que atravessa (máscara no próprio desenho)
const Crest: React.FC<{ w: number; t: number; shineAt: number }> = ({ w, t, shineAt }) => {
  const x = interpolate(t, [shineAt, shineAt + 0.7], [-60, 160], cl);
  const logo = staticFile("contas/ecmp/logo.png");
  return (
    <div style={{ position: "relative", width: w }}>
      <Img src={logo} style={{ width: w, display: "block", filter: "drop-shadow(0 18px 40px rgba(0,0,0,0.5))" }} />
      <div style={{ position: "absolute", inset: 0, WebkitMaskImage: `url(${logo})`, WebkitMaskSize: "100% 100%", maskImage: `url(${logo})`, maskSize: "100% 100%", background: `linear-gradient(105deg, rgba(255,255,255,0) ${x - 18}%, rgba(255,255,255,0.55) ${x}%, rgba(255,255,255,0) ${x + 18}%)` }} />
    </div>
  );
};
// fundo das cenas desenhadas: marinho liso com a câmera sempre andando
const Stage: React.FC<{ t: number; a: number; b: number; z0?: number; z1?: number; y0?: number; y1?: number; r0?: number; r1?: number; children: React.ReactNode }> = ({ t, a, b, z0 = 1.0, z1 = 1.06, y0 = 0, y1 = 0, r0 = 0, r1 = 0, children }) => {
  const p = io(t, a, b + 0.3);
  return (
    <AbsoluteFill style={{ background: `radial-gradient(circle at 50% 42%, ${NAVY2} 0%, ${NAVY} 70%)` }}>
      <AbsoluteFill style={{ transform: `translateY(${(y0 + (y1 - y0) * p).toFixed(1)}px) scale(${(z0 + (z1 - z0) * p).toFixed(4)}) rotate(${(r0 + (r1 - r0) * p).toFixed(2)}deg)` }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};
const col: React.CSSProperties = { position: "absolute", left: 120, right: 120, display: "flex", flexDirection: "column", alignItems: "center" };

// 0,0–1,9 · a bola entra quicando, a pergunta sobe e a bola cresce até virar a próxima cena
const Hook: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  const roll = k(t, a, 0.75);
  const x = -700 + 700 * roll;
  const hop = Math.abs(Math.sin(roll * Math.PI * 2)) * (1 - roll) * 220;
  const grow = interpolate(t, [1.5, 1.9], [1, 26], { ...cl, easing: Easing.in(Easing.cubic) });
  const txtOut = 1 - lin(t, 1.45, 1.6);
  return (
    <Stage t={t} a={a} b={b} z0={1.08} z1={1.0}>
      <div style={{ ...col, top: 470, opacity: txtOut }}>
        <Words t={t} at={0.1} text="Seu filho ama" size={130} step={0.12} shadow={false} />
        <div style={{ height: 10 }} />
        <Words t={t} at={0.66} text="futebol?" size={190} hl={["FUTEBOL"]} shadow={false} />
      </div>
      <div style={{ position: "absolute", left: 540 - 160, top: 1130 - 160, transform: `translate(${x.toFixed(1)}px, ${(-hop).toFixed(1)}px) scale(${grow.toFixed(3)})` }}>
        <Ball s={320} rot={roll * 720 + t * 40} />
      </div>
    </Stage>
  );
};

// 3,1–5,4 · o brasão cai, brilha, e o nome sobe embaixo
const CrestScene: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
