        <div style={{ ...hs(80, GOLD, false), whiteSpace: "nowrap" }}>Para um clube europeu</div>
      </div>
      <AbsoluteFill style={{ background: GOLD, opacity: flash * 0.25, pointerEvents: "none" }} />
    </Stage>
  );
};
const Drawn: React.FC<{ name: string; t: number; a: number; b: number }> = ({ name, t, a, b }) => {
  switch (name) {
    case "hook": return <Hook t={t} a={a} b={b} />;
    case "crest": return <CrestScene t={t} a={a} b={b} />;
    case "steps": return <Steps t={t} a={a} b={b} />;
    case "age1": return <Age t={t} a={a} b={b} kick="A partir de" kickAt={10.6} parts={[[10.9, "4"], [11.19, "e 5"]]} anosAt={11.6} tag="Futsal" tagAt={12.1} r={2} />;
    case "age2": return <Age t={t} a={a} b={b} kick="A partir de" kickAt={18.75} parts={[[19.29, "10"], [19.45, "+"]]} anosAt={19.5} tag="Técnica" tagAt={20.0} count={[0, 10, 0.45]} r={-2} />;
    case "age3": return <Age t={t} a={a} b={b} kick="Projeto CFC" kickAt={28.0} parts={[[27.95, "11"], [28.55, "a 15"]]} anosAt={29.18} r={2} />;
    case "grid": return <Grid t={t} a={a} b={b} />;
    case "bars": return <Bars t={t} a={a} b={b} />;
    case "quadra": return <Quadra t={t} a={a} b={b} />;
    case "locs": return <Locs t={t} a={a} b={b} />;
    case "ecmp": return <Ecmp t={t} a={a} b={b} />;
    case "venda": return <Venda t={t} a={a} b={b} />;
    default: return <End t={t} a={a} />;
  }
};

export const ContasEcmpV11: React.FC = () => {
  const tt = useCurrentFrame() / C11_FPS;
  const tn = tt - OFF;
  const t = W(tn);
  const i = Math.max(0, SHOTS.findIndex((s, j) => t >= s.a && (j + 1 >= SHOTS.length || t < SHOTS[j + 1].a)));
  const s = SHOTS[i];
  const b = i + 1 < SHOTS.length ? SHOTS[i + 1].a : C11_DUR;
  const prev = i > 0 ? SHOTS[i - 1] : undefined;
  const e = k(t, s.a, 0.42);
  const dir = i % 2 ? -1 : 1;

  let wrap: React.CSSProperties = {};
  if (s.e === "punch") wrap = { transform: `scale(${(1 + 0.16 * (1 - e)).toFixed(4)})` };
  if (s.e === "pull") wrap = { transform: `scale(${(1.22 - 0.22 * e).toFixed(4)})`, filter: `blur(${((1 - e) * 10).toFixed(1)}px)` };
  if (s.e === "slide") wrap = { transform: `translateX(${((1 - e) * 1080 * dir).toFixed(0)}px)` };
  if (s.e === "whip") wrap = { transform: `translateY(${((1 - e) * 1920 * dir).toFixed(0)}px)`, filter: `blur(${((1 - e) * 22).toFixed(1)}px)` };
  const flood = s.e === "flood" ? lin(t, s.a, s.a + 0.38) : 1;
  const floodOut = s.e === "flood" ? 1 - lin(t, s.a + 0.3, s.a + 0.62) : 0;

  const scene = (x: Shot, a: number, bb: number) => (x.src.startsWith("d:") ? <Drawn name={x.src.slice(2)} t={t} a={a} b={bb} /> : <Media s={x} t={t} b={bb} />);
  // a bola da abertura cresce e cobre a tela: a filmagem nasce do branco dela
  const showPrev = prev && t < s.a + 0.45 && !(prev.src === "d:hook");
  const footage = !s.src.startsWith("d:");
  const badge = k(t, 2.0, 0.5);
  const white = s.src === "v6" && i === 1 ? 1 - lin(t, s.a, s.a + 0.3) : 0;

  return (
    <AbsoluteFill style={{ background: NAVY }}>
      {showPrev && prev && <AbsoluteFill style={{ transform: s.e === "slide" ? `translateX(${(-e * 1080 * dir * 0.35).toFixed(0)}px)` : undefined, opacity: s.e === "slide" ? 1 - lin(t, s.a - 0.03, s.a + 0.012) : 1 }}>{scene(prev, prev.a, s.a)}</AbsoluteFill>}
      <AbsoluteFill style={{ ...wrap, clipPath: s.e === "flood" ? `circle(${(flood * 120).toFixed(1)}% at 50% 55%)` : undefined }}>{scene(s, s.a, b)}</AbsoluteFill>
      {s.e === "flood" && floodOut > 0 && <AbsoluteFill style={{ background: RED, opacity: floodOut, clipPath: `circle(${(lin(t, s.a - 0.02, s.a + 0.32) * 120).toFixed(1)}% at 50% 55%)` }} />}
      {white > 0 && <AbsoluteFill style={{ background: "#FFFFFF", opacity: white }} />}

      {footage && (
        <>
          <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(19,26,46,0.35) 0%, rgba(19,26,46,0) 14%, rgba(19,26,46,0) 44%, rgba(19,26,46,0.55) 62%, rgba(19,26,46,0.85) 80%, rgba(19,26,46,0.9) 100%)` }} />
          <div style={{ position: "absolute", left: 0, right: 0, top: 270, display: "flex", justifyContent: "center", opacity: s.src.startsWith("p") ? 0 : badge }}>
            <Img src={staticFile("contas/ecmp/logo.png")} style={{ width: 150, filter: "drop-shadow(0 6px 16px rgba(0,0,0,0.5))" }} />
          </div>
        </>
      )}
      {CAPS.map((c, j) => <CapBlock key={j} c={c} t={t} />)}

      <Audio src={staticFile("contas/ecmp/mix-v11.wav")} />
    </AbsoluteFill>
  );
};

